def lbs(arr):
    n = len(arr)
    if n <= 1:
        return n

    # Initialize the dp array where dp[i][j] represents the length of the longest bitonic subsequence ending at arr[i] and arr[j]
    dp = [[0] * n for _ in range(n)]

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i][j] = dp[j][i] + 1
            elif arr[i] < arr[j]:
                dp[i][j] = max(dp[i][j], dp[j][i - 1] + 1)

    # The maximum value in the dp array will be the length of the longest bitonic subsequence
    return max(dp[i][j] for i in range(n))
```

