def modular_sum(arr, n, m):
    # Helper function to check if there exists a subset with sum divisible by m
    def can_partition_with_sum(arr, n, m, current_sum, target):
        if current_sum == target:
            return True
        if current_sum > target:
            return False
        for i in range(n):
            if can_partition_with_sum(arr, n, m, current_sum + arr[i], target):
                return True
        return False

    # Check all possible sums from 0 to m-1
    for i in range(m):
        if can_partition_with_sum(arr, n, m, 0, i):
            return True
    return False
```

